actions.script:
// the org limit is a trusted filter, so it does not change scores and the user query cannot widen it
let ownerPartyIds = null;
if ('MANTLE_USER_ORG' === entityFilterSetId) ownerPartyIds = (filterOrgIds || []).concat(['_NA_']);
else if ('MANTLE_ACTIVE_ORG' === entityFilterSetId && activeOrgId) ownerPartyIds = [activeOrgId, '_NA_'];
// a personal contact (privateOwnerUserId) only for its owner, with or without an org filter, as trusted
const privateFilter = ec.user.userId ? {bool: {any: [{field: {name: 'privateOwnerUserId', op: 'exists', negate: true}},
        {field: {name: 'privateOwnerUserId', op: 'eq', value: ec.user.userId}}]}}
        : {field: {name: 'privateOwnerUserId', op: 'exists', negate: true}};
filter = ownerPartyIds != null ? {bool: {all: [{field: {name: 'ownerPartyId', op: 'in', values: ownerPartyIds}}, privateFilter]}}
        : privateFilter;

service-call.in-map:
{indexName:indexName, documentType:documentType, queryString:queryString, flattenDocument:false,
                             orderByFields:orderByFields, highlightFields:highlightFields, nestedQueryMap:nestedQueryMap, filter:filter,
                             pageIndex:pageIndex, pageSize:pageSize, pageNoLimit:pageNoLimit}

actions.script:
counts = {}
failedParts = []
const currentUserId = ec.user.userId || null
if (!userId) userId = currentUserId
if (!userId) return
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (userId !== currentUserId && !wasDisabled) {
        ec.message.addError("Another user's shell counts are read only with authorization disabled")
        counts = null
        return
    }
    // one part: its errors are its own; a failure leaves its counts null
    const part = (name, keys, run) => {
        ec.message.pushErrors()
        try {
            const values = run()
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            for (const key of keys) counts[key] = values[key] ?? 0
        } catch (err) {
            for (const key of keys) counts[key] = null
            failedParts.push(name)
            ec.logger.error(`Shell counts of user ${userId}: the ${name} count failed and is left out: ${err && err.message ? err.message : err}`)
        } finally {
            ec.message.clearErrors()
            ec.message.popErrors()
        }
    }
    // each part in a transaction of its own: an error in one marks only its own transaction rollback-only
    const callService = (name, parameters) => {
        const out = ec.service.sync().name(name).parameters(parameters).requireNewTransaction(true).call()
        if (out == null) throw new Error(`${name} answered nothing`)
        return out
    }
    part('today', ['today', 'overdue'], () => {
        const items = callService('mantle.work.WorkEffortServices.get#UserTodayItems', {userId: userId, countOnly: true})
        if (items.failedSources?.length) throw new Error(items.failedSources.map((failure) => failure.message).join('; '))
        return {today: items.overdue.length + items.dueToday.length, overdue: items.overdue.length}
    })
    part('notifications', ['notifications', 'approvals', 'updates'], () => {
        const out = callService('mantle.party.PartyServices.count#UserNotifications', {userId: userId})
        return {notifications: out.notificationCount, approvals: out.approvalCount, updates: out.updateCount}
    })
    part('messages', ['messages'], () => ({messages: callService('mantle.party.CommunicationServices.count#UnreadInternalMessages', {userId: userId}).unreadCount}))
    part('email', ['email'], () => ({email: callService('org.moqui.impl.EmailClientServices.count#UnreadEmail', {userId: userId}).unreadCount}))
    part('chat', ['chat'], () => ({chat: callService('org.moqui.impl.ChatServices.get#UnreadCounts', {userId: userId}).total}))
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

notificationCount = 0
approvalCount = 0
updateCount = 0
if (!userId) userId = ec.user.userId
if (!userId) return
if (userId !== ec.user.userId) {
    const wasDisabled = ec.artifactExecution.disableAuthz()
    if (!wasDisabled) {
        ec.artifactExecution.enableAuthz()
        ec.message.addError("Another user's notifications are counted only with authorization disabled")
        return
    }
}
const unviewed = ec.entity.find('moqui.security.user.NotificationMessageUser').condition('userId', userId)
        .condition('viewedDate', null).disableAuthz().count()
if (unviewed === 0) return
const topicRows = Array.from(ec.entity.find('moqui.security.user.NotificationTopic').useCache(true).disableAuthz().list())
const updateTopics = topicRows.filter((topic) => topic.inboxEnumId === 'NinUpdates' && !topic.approveServiceName)
        .map((topic) => topic.topic)
const approvalTopics = topicRows.filter((topic) => topic.approveServiceName).map((topic) => topic.topic)
const countOf = (topics) => topics.length === 0 ? 0 : ec.entity.find('moqui.security.user.NotificationMessageByUser')
        .condition('userId', userId).condition('viewedDate', null).condition('topic', 'in', topics).disableAuthz().count()
updateCount = countOf(updateTopics)
notificationCount = unviewed - updateCount
approvalCount = countOf(approvalTopics)

publishedUserIds = []
const userIds = new Set((userIdList ? Array.from(userIdList) : []).filter((id) => id))
const partyIds = Array.from(new Set((partyIdList ? Array.from(partyIdList) : []).filter((id) => id)))
ec.message.pushErrors()
try {
    if (partyIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('partyId', 'in', partyIds)
            .selectField('userId').disableAuthz().list()) userIds.add(account.userId)
    if (userIds.size === 0) return
    const users = Array.from(userIds)
    ec.service.sync().name('org.moqui.impl.ShellServices.publish#ShellCounts').parameters({userIdList: users}).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    publishedUserIds = users
} catch (err) {
    ec.logger.error(`Could not publish the shell counts of users ${Array.from(userIds)} (parties ${partyIds}): ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

service.description:
For the entity ECAs of ShellCounts.eecas.xml: whether a write changed what get#ShellCounts counts and, when it
did, the counts of the users it touches published (publish#PartyShellCounts). A create or a delete is a change;
an update is one when a counted field of newValues differs from oldValues, the row before the write (none is a
change). The counted fields: WorkEffortParty statusId, thruDate and snoozedThruDate; WorkEffort statusId,
workEffortTypeEnumId, estimatedStartDate, estimatedCompletionDate, allDayStart and allDayEnd;
NotificationMessageUser viewedDate; CommunicationEventParty readDate, archivedDate and snoozedThruDate;
EmailMessage isRead, archivedDate, emailFolderId and snoozedThruDate, of an unread message (before or after the
write; a read message changes no count). The users: those of the WorkEffortParty's or CommunicationEventParty's
party, the NotificationMessageUser's user, those of a WorkEffort's parties in effect, the owner and current
members of an EmailMessage's account (emailAccountId). Never fails the write: a failure is logged.

actions.script:
changed = false
publishedUserIds = []
const counted = {
    'mantle.work.effort.WorkEffortParty': ['statusId', 'thruDate', 'snoozedThruDate'],
    'mantle.work.effort.WorkEffort': ['statusId', 'workEffortTypeEnumId', 'estimatedStartDate', 'estimatedCompletionDate',
        'allDayStart', 'allDayEnd'],
    'moqui.security.user.NotificationMessageUser': ['viewedDate'],
    'mantle.party.communication.CommunicationEventParty': ['readDate', 'archivedDate', 'snoozedThruDate'],
    'moqui.basic.email.EmailMessage': ['isRead', 'archivedDate', 'emailFolderId', 'snoozedThruDate']}
const fields = counted[entityName]
if (!fields) return
const plain = (value) => value == null || value === '' ? null : (value instanceof Date ? String(value.getTime()) : String(value))
ec.message.pushErrors()
try {
    changed = eecaOperation !== 'update' || oldValues == null ||
            fields.some((field) => plain(newValues?.[field]) !== plain(oldValues[field]))
    // mail counts only unread messages: a read one that moves, or is created or deleted read, changes no count
    if (changed && entityName === 'moqui.basic.email.EmailMessage') {
        const unreadAfter = newValues?.isRead !== 'Y'
        const unreadBefore = oldValues != null && oldValues.isRead !== 'Y'
        changed = !!emailAccountId && (eecaOperation === 'create' ? unreadAfter
                : (eecaOperation === 'delete' ? (oldValues != null ? unreadBefore : unreadAfter) : unreadAfter || unreadBefore))
    }
    if (!changed) return
    const parameters = {}
    if (entityName === 'moqui.security.user.NotificationMessageUser') {
        parameters.userIdList = [userId]
    } else if (entityName === 'moqui.basic.email.EmailMessage') {
        const users = new Set()
        const account = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', emailAccountId).disableAuthz().one()
        if (account?.ownerUserId) users.add(account.ownerUserId)
        for (const row of ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', emailAccountId)
                .conditionDate('fromDate', 'thruDate', null).disableAuthz().list()) users.add(row.userId)
        parameters.userIdList = Array.from(users)
    } else if (entityName === 'mantle.work.effort.WorkEffort') {
        parameters.partyIdList = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId)
                .condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', ec.user.nowTimestamp))
                .selectField('partyId').disableAuthz().list()).map((row) => row.partyId)
    } else {
        parameters.partyIdList = [partyId]
    }
    const out = ec.service.sync().name('mantle.party.PartyServices.publish#PartyShellCounts').parameters(parameters).call()
    publishedUserIds = out?.publishedUserIds ?? []
} catch (err) {
    ec.logger.error(`Shell counts after a ${eecaOperation} of ${entityName} not published: ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

// every non-empty value of key in the maps and lists nested in value, without duplicates
function findAllFieldsNestedMap(key, value, found) {
    if (Array.isArray(value)) {
        for (const item of value) findAllFieldsNestedMap(key, item, found)
    } else if (value != null && typeof value === 'object') {
        for (const [name, item] of Object.entries(value)) {
            if (name === key && item != null && item !== '' && !found.includes(item)) found.push(item)
            findAllFieldsNestedMap(key, item, found)
        }
    }
}

iterate.script:
const nm = ec.makeNotificationMessage()
nm.topic(String(document._type)).message(document)
if (userIdSet.length > 0) nm.userIds(userIdSet)
const notificationTopic = nm.getNotificationTopic()
if (notificationTopic == null && document._type) {
    const dataDocument = ec.entity.find("moqui.entity.document.DataDocument").condition("dataDocumentId", document._type).useCache(true).one()
    if (dataDocument.documentTitle) nm.title(dataDocument.documentTitle)
    const dataDocumentLinks = dataDocument.findRelated("links", null, null, true, false)
    if (dataDocumentLinks.length > 0) nm.link(dataDocumentLinks[0].linkUrl)
}
nm.send()
